namespace sv_6695e090a2f44805a21b30f3382b1070.Services;

public class WarehouseInfo
{
    public required string Id { get; init; }
    public required string Name { get; init; }
}

/// <summary>
/// Scoped service that tracks which warehouse the current user has selected.
/// Per-circuit on Server, so each user gets independent state.
/// </summary>
public class WarehouseState
{
    private static readonly List<WarehouseInfo> _allWarehouses =
    [
        new() { Id = "WH-001", Name = "Warehouse A — East" },
        new() { Id = "WH-002", Name = "Warehouse B — West" },
        new() { Id = "WH-003", Name = "Warehouse C — Central" },
    ];

    public IReadOnlyList<WarehouseInfo> Warehouses => _allWarehouses;

