@rendermode InteractiveServer
@inject WarehouseState Warehouse
@implements IDisposable

<select class="form-select form-select-sm" value="@Warehouse.CurrentWarehouseId"
        @onchange="OnWarehouseChanged" style="max-width: 240px;">
    @foreach (var wh in Warehouse.Warehouses)
    {
        <option value="@wh.Id">@wh.Name</option>
    }
</select>

@code {
    private void OnWarehouseChanged(ChangeEventArgs e)
    {
        var id = e.Value?.ToString();
        if (!string.IsNullOrEmpty(id))
        {
            Warehouse.SetWarehouse(id);
        }
    }

    // Re-render if another component changes the warehouse (unlikely but safe).
    private Action? _handler;

    protected override void OnInitialized()
    {
        _handler = () => InvokeAsync(StateHasChanged);
        Warehouse.OnChange += _handler;
    }

    public void Dispose() => Warehouse.OnChange -= _handler;
}

@rendermode InteractiveServer
@using sv_6695e090a2f44805a21b30f3382b1070.Services
@inject InventoryAlertService AlertService
@implements IDisposable

@if (AlertService.LowStockCount > 0)
{
    <span class="badge bg-danger rounded-pill ms-auto">@AlertService.LowStockCount</span>
}

@code {
    private Action? _handler;

    protected override void OnInitialized()
    {
        _handler = () => InvokeAsync(StateHasChanged);
        AlertService.OnAlertCountChanged += _handler;
    }

    public void Dispose() => AlertService.OnAlertCountChanged -= _handler;
}

