 @code {
     private PeriodicTimer? _timer;
     private CancellationTokenSource? _cts;
     private bool _isPolling;
     private Action? _warehouseHandler;
     private Action? _alertHandler;

     protected override void OnInitialized()
     {
         // Subscribe to warehouse changes so the dashboard card updates immediately.
         _warehouseHandler = () => InvokeAsync(StateHasChanged);
         Warehouse.OnChange += _warehouseHandler;

         // Subscribe to alert count changes (fired by the polling loop below).
         _alertHandler = () => InvokeAsync(StateHasChanged);
         AlertService.OnAlertCountChanged += _alertHandler;
     }

     protected override async Task OnAfterRenderAsync(bool firstRender)
     {
         if (firstRender)
         {
             // Fetch once immediately, then start the 10-second poll.
             await PollOnceAsync();
             _ = StartPollingAsync();
         }
     }

     private async Task StartPollingAsync()
     {
         _cts = new CancellationTokenSource();
         _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
         _isPolling = true;
         await InvokeAsync(StateHasChanged);

         try
         {
             while (await _timer.WaitForNextTickAsync(_cts.Token))
             {
                 await PollOnceAsync();
             }
         }
         catch (OperationCanceledException)
         {
             // Expected on dispose.
         }
     }

     private async Task PollOnceAsync()
     {
         var count = await AlertService.GetLowStockCountAsync(Warehouse.CurrentWarehouseId);
         // UpdateCount fires OnAlertCountChanged, which re-renders ALL subscribers
         // (this page AND the sidebar AlertBadge).
         AlertService.UpdateCount(count);
     }

     public void Dispose()
     {
         Warehouse.OnChange -= _warehouseHandler;
         AlertService.OnAlertCountChanged -= _alertHandler;

         _cts?.Cancel();
         _cts?.Dispose();
         _timer?.Dispose();
         _isPolling = false;
     }
